// @ts-strict-ignore
import { EventAggregator } from "@/core/helpers";
import styles from "./restaurant-wait-time-modal.module.less";
import { RestaurantBlockType } from "@/core/components/primitives/restaurant-list-item/restaurant-list-item-enums";
import { PrimaryButton, SecondaryButtonLink } from "@/core/components/primitives/parks-button/parks-button";
import { Modal } from "@/core/components/primitives/modal/modal";
import { useContentContainerRef } from "@/core/components/primitives/content-container/content-container";
import { MODAL_PORTAL_ID } from "@/core/components/primitives/modal-portal/modal-portal";
import { useTranslation } from "react-i18next";

const handleClick = (cancel, hideModal) => {
  EventAggregator.publish("trackEvent", {
    category: "Restaurant List Item",
    action: "Wait Time Modal",
    label: cancel ? "back" : "continue",
  });
  hideModal();
};

const ContinueButton = ({ hideModal, url, label }) => (
  <span onClick={() => handleClick(false, hideModal)}>
    <SecondaryButtonLink complementary url={url} label={label} />
  </span>
);

type Props = {
  hideModal: () => void;
  waitTimeLabel: string;
  modalType: RestaurantBlockType;
  directPejLink?: string;
  linkUrl?: string;
  labels: {
    restaurantWaitTimeModalHeaderFullQueue?: string;
    restaurantWaitTimeModalHeaderLongQueue?: string;
    restaurantWaitTimePaused?: string;
    restaurantGoBack?: string;
    restaurantContinue?: string;
  };
};

const RestaurantWaitTimeModal = ({ hideModal, waitTimeLabel, modalType, linkUrl, labels }: Props) => {
  const { t } = useTranslation();
  const wrapperElement = useContentContainerRef();

  const isHardBlock = modalType === RestaurantBlockType.HARD_BLOCK;

  const modalTitle = isHardBlock
    ? labels.restaurantWaitTimeModalHeaderFullQueue ?? t("restaurantWaitTimeModalHeaderFullQueue")
    : labels.restaurantWaitTimeModalHeaderLongQueue ?? t("restaurantWaitTimeModalHeaderLongQueue");

  const modalBody = isHardBlock ? labels.restaurantWaitTimePaused ?? t("restaurantWaitTimePaused") : waitTimeLabel;

  const shouldRenderContinueButton = () => {
    if (!linkUrl) {
      return false;
    }

    return isHardBlock ? false : true;
  };

  return (
    <Modal
      className={styles.modalWrapper}
      modalTitle="modalTitle"
      portalId={MODAL_PORTAL_ID}
      isOpen={true}
      refWrapperElement={wrapperElement}
      disableInitialFocusInModal={true}
      onClose={() => hideModal()}
    >
      <div className={styles.modal}>
        <h4 id="modalTitle" className={styles.modalTitle}>
          {modalTitle}
        </h4>
        <div className={styles.modalWaitTime}>{modalBody}</div>
        <div className={styles.buttonWrapper}>
          <PrimaryButton
            label={labels.restaurantGoBack ?? t("restaurantGoBack")}
            className={styles.cancelButton}
            onClick={() => handleClick(true, hideModal)}
          />
          {shouldRenderContinueButton() && (
            <ContinueButton
              hideModal={hideModal}
              url={linkUrl}
              label={labels.restaurantContinue ?? t("restaurantContinue")}
            />
          )}
        </div>
      </div>
    </Modal>
  );
};

export default RestaurantWaitTimeModal;
