// @ts-strict-ignore
import { useState, ReactNode } from "react";
import { useTranslation } from "react-i18next";
import styles from "./restaurant-list-item.module.less";
import Link from "@/core/components/primitives/link/link";
import { motion } from "framer-motion";
import Label from "@/core/components/primitives/label/label";
import RestaurantWaitTimeModal from "@/core/components/primitives/restaurant-wait-time-modal/restaurant-wait-time-modal";
import { lowerCaseAndRemoveSpecialCharacters } from "@/core/helpers";
import { ExistingThemes } from "@/core/types/existing-themes";
import { GatsbyImage, IGatsbyImageData } from "gatsby-plugin-image";
import { LinkType, RestaurantBlockType } from "./restaurant-list-item-enums";

type CardProps = {
  imgUrl?: string;
  image?: IGatsbyImageData;
  imageAlt?: string;
  title: string;
  bodyText: string;
  foodTerminalId: number;
  isParkOpenNow: boolean;
  labels: {
    labelUnderImage?: string;
    readMore: string;
    waitTimeLabel?: string;
  };
  linkUrl?: string;
};

const Card = ({
  imgUrl,
  image,
  imageAlt,
  title,
  bodyText,
  foodTerminalId,
  isParkOpenNow,
  labels,
  linkUrl,
}: CardProps) => {
  return (
    <div>
      {labels.waitTimeLabel && foodTerminalId && isParkOpenNow && (
        <motion.div animate={{ opacity: 1 }} transition={{ duration: 0.5 }} className={styles.waitTimeLabel}>
          <Label title={labels.waitTimeLabel} />
        </motion.div>
      )}
      <div className={styles.imageContainer}>
        {image && <GatsbyImage image={image} alt={imageAlt ?? title} className={styles.gatsbyImage} />}
        {!image && imgUrl && <div className={styles.image} style={{ backgroundImage: `url(${imgUrl})` }} />}
        {labels.labelUnderImage && (
          <div className={styles.labelWrapper}>
            <Label title={labels.labelUnderImage} />
          </div>
        )}
        {linkUrl && (
          <div className={styles.overlayWrapper}>
            <span className={[styles.overlayButton, "p"].join(" ")}>{labels.readMore}</span>
          </div>
        )}
      </div>
      <div className={styles.textContainer}>
        {title && <h5 className={styles.headline}>{title}</h5>}
        {bodyText && <p className={["body-s", styles.shortDescription].join(" ")}>{bodyText}</p>}
      </div>
    </div>
  );
};

type CardWrapperProps = {
  children: ReactNode;
  linkUrl?: string;
  linkType: LinkType;
  shouldRenderWarningModalOnClick: boolean;
  onClickWarningCard: () => void;
};

const CardWrapper = ({
  children,
  linkUrl,
  linkType,
  shouldRenderWarningModalOnClick,
  onClickWarningCard,
}: CardWrapperProps) => {
  const shouldRenderLink = !!linkUrl;
  if (shouldRenderWarningModalOnClick) {
    return (
      <button onClick={onClickWarningCard} className={styles.triggerModalButton}>
        {children}
      </button>
    );
  }

  if (shouldRenderLink) {
    return linkType === LinkType.EXTERNAL ? (
      <Link className={styles.link} externalLink={linkUrl}>
        {" "}
        {children}{" "}
      </Link>
    ) : (
      <Link className={styles.link} internalLink={linkUrl}>
        {" "}
        {children}{" "}
      </Link>
    );
  }

  return <span className={styles.link}>{children}</span>;
};

const getCardBlockType = (shouldShowBlockingModal: boolean, shouldShowWarningModal: boolean) => {
  if (shouldShowBlockingModal) {
    return RestaurantBlockType.HARD_BLOCK;
  }
  if (shouldShowWarningModal) {
    return RestaurantBlockType.SOFT_BLOCK;
  }
  return RestaurantBlockType.NO_BLOCK;
};

const getWaitTimeLabel = (
  blockType: RestaurantBlockType,
  restaurantWaitTimeLabelPrefix: string,
  restaurantWaitTimeFullQueue: string,
  waitTimeLabel: string | undefined,
): string | undefined => {
  switch (blockType) {
    case RestaurantBlockType.HARD_BLOCK:
      return restaurantWaitTimeLabelPrefix + restaurantWaitTimeFullQueue;
    case RestaurantBlockType.SOFT_BLOCK:
    case RestaurantBlockType.NO_BLOCK: {
      if (waitTimeLabel) {
        return restaurantWaitTimeLabelPrefix + waitTimeLabel;
      }
      return undefined;
    }
    default:
      return undefined;
  }
};

export type RestaurantListItemProps = {
  /**
   * @deprecated
   * Use prop `image` instead.
   */
  imageUrl?: string;
  /**
   * @example
   * Use the following query to get the correct image size for `image`:
   * gatsbyImageData(width: 312, height: 224, layout: CONSTRAINED, quality: 100)
   */
  image?: IGatsbyImageData;
  imageAlt?: string;
  title: string;
  bodyText: string;
  linkUrl?: string;
  linkType: LinkType;
  extraClass?: string;
  componentTheme?: ExistingThemes;
  foodTerminalId: number;
  shouldShowWarningModal: boolean;
  shouldShowBlockingModal: boolean;
  isParkOpenNow?: boolean;
  labels: {
    labelUnderImage?: string;
    waitTimeLabel?: string;
    restaurantWaitTimeLabelPrefix?: string;
    restaurantWaitTimeFullQueue?: string;
    readMore?: string;
    restaurantWaitTimeModalHeaderFullQueue?: string;
    restaurantWaitTimeModalHeaderLongQueue?: string;
    restaurantWaitTimePaused?: string;
    restaurantGoBack?: string;
    restaurantContinue?: string;
  };
};

const RestaurantListItem = (props: RestaurantListItemProps) => {
  const { t } = useTranslation();
  const [showModal, setShowModal] = useState(false);

  const cardBlockType = getCardBlockType(props.shouldShowBlockingModal, props.shouldShowWarningModal);

  const waitTimeLabel = getWaitTimeLabel(
    cardBlockType,
    props.labels.restaurantWaitTimeLabelPrefix ?? t("restaurantWaitTimeLabelPrefix").toUpperCase(),
    props.labels.restaurantWaitTimeFullQueue ?? t("restaurantWaitTimeFullQueue"),
    props.labels.waitTimeLabel,
  );

  const { extraClass = "", componentTheme = "" } = props;

  return (
    <div className={[styles.restaurant, extraClass, componentTheme].join(" ")}>
      <div id={lowerCaseAndRemoveSpecialCharacters(props.title)} className={styles.anchorWrapper} />
      {showModal && (
        <RestaurantWaitTimeModal
          hideModal={() => {
            setShowModal(false);
          }}
          waitTimeLabel={props.labels.waitTimeLabel}
          modalType={cardBlockType}
          linkUrl={props.linkUrl}
          labels={{
            restaurantWaitTimeModalHeaderFullQueue: props.labels?.restaurantWaitTimeModalHeaderFullQueue,
            restaurantWaitTimeModalHeaderLongQueue: props.labels?.restaurantWaitTimeModalHeaderLongQueue,
            restaurantWaitTimePaused: props.labels?.restaurantWaitTimePaused,
            restaurantGoBack: props.labels?.restaurantGoBack,
            restaurantContinue: props.labels?.restaurantContinue,
          }}
        />
      )}
      <CardWrapper
        linkUrl={props.linkUrl}
        linkType={props.linkType}
        shouldRenderWarningModalOnClick={
          cardBlockType === RestaurantBlockType.HARD_BLOCK || cardBlockType === RestaurantBlockType.SOFT_BLOCK
        }
        onClickWarningCard={() => {
          setShowModal(true);
        }}
      >
        <Card
          imgUrl={props.imageUrl}
          image={props.image}
          imageAlt={props.imageAlt}
          title={props.title}
          bodyText={props.bodyText}
          foodTerminalId={props.foodTerminalId}
          isParkOpenNow={props.isParkOpenNow ?? true}
          labels={{
            labelUnderImage: props.labels.labelUnderImage,
            readMore: props.labels.readMore ?? t("readMore"),
            waitTimeLabel: waitTimeLabel,
          }}
          linkUrl={props.linkUrl}
        />
      </CardWrapper>
    </div>
  );
};

export default RestaurantListItem;
